Bash cat >> e2e/club.spec.ts <<'EOF'

// The answer buttons, and one group of names, on the club page.
const answerButton = (page: Page, label: string) => page.getByRole("button", { name: label, exact: true });
const namesUnder = (page: Page, label: string) => page.getByRole("list", { name: new RegExp(`^${label} \\(`) });

test("a member answers, changes their mind, and everyone sees it", async ({ page }) => {
  await signIn(page, "ben@example.com");

  await answerButton(page, "Maybe").click();
  await expect(answerButton(page, "Maybe")).toHaveAttribute("aria-pressed", "true");
  await expect(namesUnder(page, "Maybe")).toContainText("Ben (you)");

  // Changing your mind moves you, by keyboard too.
  await answerButton(page, "Going").focus();
  await page.keyboard.press("Enter");
  await expect(answerButton(page, "Going")).toHaveAttribute("aria-pressed", "true");
  await expect(answerButton(page, "Maybe")).toHaveAttribute("aria-pressed", "false");
  await expect(namesUnder(page, "Going")).toContainText("Ben (you)");
  await expect(namesUnder(page, "Maybe")).toHaveCount(0);

  // It's saved, not just shown.
  await page.reload();
  await expect(answerButton(page, "Going")).toHaveAttribute("aria-pressed", "true");
  await shot(page, "rsvp-going");

  // Someone else sees Ben going.
  await page.getByRole("button", { name: "Sign out" }).click();
  await expect(page).toHaveURL("/sign-in");
  await signIn(page, "chloe@example.com");
  await expect(namesUnder(page, "Going")).toContainText("Ben");
  await expect(namesUnder(page, "Going")).not.toContainText("(you)");
});

test("a failed save puts the old answer back and says so", async ({ page }) => {
  await signIn(page, "dev@example.com");
  await answerButton(page, "Going").click();
  await expect(namesUnder(page, "Going")).toContainText("Dev (you)");

  // Drop the connection for the next save.
  await page.route("**/*", (route) =>
    route.request().method() === "POST" ? route.abort("internetdisconnected") : route.continue(),
  );
  await answerButton(page, "Can't go").click();

  await expect(page.getByRole("alert")).toContainText("Couldn't save your answer");
  await expect(answerButton(page, "Going")).toHaveAttribute("aria-pressed", "true");
  await expect(answerButton(page, "Can't go")).toHaveAttribute("aria-pressed", "false");
  await expect(page.getByRole("heading", { name: "Who's coming" })).toBeVisible();
  await shot(page, "rsvp-failed");

  // Back online, the same tap works.
  await page.unrouteAll();
  await answerButton(page, "Can't go").click();
  await expect(namesUnder(page, "Can't go")).toContainText("Dev (you)");
  await expect(page.getByRole("alert")).toHaveCount(0);
});
EOF
